    reg [31:0] scratch_q;
    reg [31:0] config_q;
    reg [31:0] status_q;
    reg [31:0] wcount_q;
    reg [7:0] mask_q;
    reg [7:0] pend_q;

    wire [7:0] w1c_clear =
        (wr_en && (wr_idx == 3'd4) && wr_strb[0]) ? wr_data[7:0] : 8'd0;

    axil_wr_if u_axil_wr_if (
        .clk(clk),
        .rst(rst),
        .awvalid(awvalid),
        .awready(awready),
        .awaddr(awaddr),
        .wvalid(wvalid),
