        .wr_idx(wr_idx),
        .wr_data(wr_data),
        .wr_strb(wr_strb)
    );

    axil_rd_if u_axil_rd_if (
        .clk(clk),
        .rst(rst),
        .arvalid(arvalid),
        .arready(arready),
        .araddr(araddr),
        .rvalid(rvalid),
        .rready(rready),
        .rdata(rdata),
        .rresp(rresp),
        .regs_flat(regs_flat)
    );

    always @(posedge clk) begin
        if (rst) begin
            ctrl_q <= 32'd0;
            scratch_q <= 32'd0;
            config_q <= 32'h00000100;
            mask_q <= 8'd0;
            pend_q <= 8'd0;
            status_q <= 32'd0;
            wcount_q <= 32'd0;
        end else begin
            status_q <= status_in;
            pend_q <= (pend_q & ~w1c_clear) | irq_set;

            if (wr_en)
                wcount_q <= wcount_q + 32'd1;

            if (wr_en && (wr_idx == 3'd0)) begin
                if (wr_strb[0]) ctrl_q[7:0]   <= wr_data[7:0];
                if (wr_strb[1]) ctrl_q[15:8]  <= wr_data[15:8];
                if (wr_strb[2]) ctrl_q[23:16] <= wr_data[23:16];
                if (wr_strb[3]) ctrl_q[31:24] <= wr_data[31:24];
            end

