                if (wr_strb[1]) scratch_q[15:8]  <= wr_data[15:8];
                if (wr_strb[2]) scratch_q[23:16] <= wr_data[23:16];
                if (wr_strb[3]) scratch_q[31:24] <= wr_data[31:24];
            end

            if (wr_en && (wr_idx == 3'd2)) begin
                if (wr_strb[0]) config_q[7:0]   <= wr_data[7:0];
                if (wr_strb[1]) config_q[15:8]  <= wr_data[15:8];
                if (wr_strb[2]) config_q[23:16] <= wr_data[23:16];
                if (wr_strb[3]) config_q[31:24] <= wr_data[31:24];
            end

            if (wr_en && (wr_idx == 3'd3) && wr_strb[0])
                mask_q <= wr_data[7:0];
        end
    end

    assign regs_flat = {
        wcount_q,
        32'h52544C35,
        status_q,
        {24'd0, pend_q},
        {24'd0, mask_q},
        config_q,
        scratch_q,
        ctrl_q
    };
    assign ctrl = ctrl_q;
    assign irq = |(pend_q & mask_q);
